import { readFileSync } from "node:fs";
import path from "node:path";

import { expect, sample, test, uniqueName } from "../../fixtures";

test.describe("upload vendor documents", () => {
  test("upload a document", { tag: "@DOC-01" }, async ({ apiAs }) => {
    // Arrange: a draft vendor owned by the member's tenant
    const member = await apiAs("member");
    const vendorRes = await member.post("/api/vendors", {
      data: {
        name: uniqueName("Doc Vendor"),
        category: "services",
        contact_email: `doc-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@example.com`,
      },
    });
    expect(vendorRes.status(), await vendorRes.text()).toBe(201);
    const vendor = await vendorRes.json();
    expect(vendor.status).toBe("draft");

    // Act: upload the insurance certificate
    const fileName = "insurance_certificate.txt";
    const res = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "insurance_certificate",
        file: {
          name: fileName,
          mimeType: "text/plain",
          buffer: readFileSync(sample(path.basename(fileName))),
        },
      },
    });

    // Assert
    expect(res.status(), await res.text()).toBe(201);
    const doc = await res.json();
    expect(doc.status).toBe("processing");
    expect(doc.kind).toBe("insurance_certificate");
    expect(doc.vendor_id).toBe(vendor.id);

    await expect
      .poll(
        async () => {
          const auditRes = await member.get(`/api/vendors/${vendor.id}/audit`);
          expect(auditRes.status(), await auditRes.text()).toBe(200);
          const body = (await auditRes.json()) as { items: { action: string }[] };
          return body.items.map((item) => item.action);
        },
        { message: "document.uploaded audit event recorded" },
      )
      .toContain("document.uploaded");
  });
});
